export const QUESTIONS_307A = [
  // ═══ BLOCK A: Common Occupational Skills (16) ═══
  {id:1,cat:"A",q:"What is the minimum hydrostatic test pressure for a steam piping system per B51?",opts:["Operating pressure","1.5 × maximum allowable working pressure (MAWP)","50 PSI","Equal to design pressure"],ans:1,exp:"CSA B51 requires hydrostatic testing at 1.5× MAWP for steam and pressure piping. The test is held for a minimum duration while inspecting for leaks. Never use pneumatic test without engineering approval.",type:"recall"},
  {id:2,cat:"A",q:"ASME B31.1 covers:",opts:["Plumbing drains","Power piping (steam, high-temperature water in power plants and industrial facilities)","Residential gas piping","Refrigeration only"],ans:1,exp:"B31.1 Power Piping: steam, condensate, and high-temperature water in power plants, industrial plants, and heating systems. B31.3 covers process piping. B31.9 covers building services.",type:"recall"},
  {id:3,cat:"A",q:"When reading a P&ID, a line with double slashes indicates:",opts:["Drain line","An insulated pipe","A flex connector","An electrical line"],ans:1,exp:"Double slashes (or II marks) across a pipe line on a P&ID indicate insulation. Different P&ID standards may vary, but this is the most common convention.",type:"recall"},
  {id:4,cat:"A",q:"A spool sheet (spool drawing) provides:",opts:["Equipment specifications only","Detailed fabrication information for a pre-fabricated pipe assembly (isometric, dimensions, materials, welds)","Electrical wiring","HVAC ductwork"],ans:1,exp:"Spool sheets are fabrication drawings for individual pipe assemblies (spools) to be prefabricated in the shop. They include isometric views, dimensions, weld locations, materials, and BOM.",type:"recall"},
  {id:5,cat:"A",q:"The piping specification (pipe spec) defines:",opts:["Only pipe size","Material, schedule, fitting type, flange rating, gasket type, and valve type for each service class","Only the colour","Only the manufacturer"],ans:1,exp:"Pipe specs define ALL components for a given service: pipe material/grade/schedule, fitting type/rating, flange class, gasket material, bolt grade, valve type — ensuring compatibility.",type:"recall"},
  {id:6,cat:"A",q:"When performing hot work near piping containing flammable substances, what is required?",opts:["Nothing special","A hot work permit, fire watch, atmospheric monitoring, and purging/isolation of the piping","Just a fire extinguisher","Only supervisor notification"],ans:1,exp:"Hot work permits, continuous fire watch, atmospheric gas testing, and proper purging/isolation of adjacent piping are mandatory. Many incidents occur from inadequate purging.",type:"procedure"},
  {id:7,cat:"A",q:"CSA B51 is the Canadian standard for:",opts:["Electrical installations","Boiler, pressure vessel, and pressure piping code","Plumbing code","Fire alarm code"],ans:1,exp:"CSA B51 governs the design, construction, installation, and inspection of boilers, pressure vessels, and pressure piping in Canada. Provincial regulations adopt and enforce it.",type:"recall"},
  {id:8,cat:"A",q:"A steamfitter's offset calculation for a rolling offset uses the formula:",opts:["Simple offset only","True offset = √(horizontal offset² + vertical offset²), then travel = true offset × fitting constant","Only horizontal measure","Only vertical measure"],ans:1,exp:"Rolling offset: find the true offset first using Pythagorean theorem, then multiply by the fitting constant (1.414 for 45°, 2.0 for 60°, 2.613 for 22.5°).",type:"critical"},
  {id:9,cat:"A",q:"Pipe schedule determines:",opts:["Pipe colour","Wall thickness for a given nominal pipe size","Pipe length","Pipe material"],ans:1,exp:"Schedule (40, 80, 160, etc.) defines wall thickness. Higher schedule = thicker wall = higher pressure rating. Schedule 40 is standard, Schedule 80 for higher pressures, XXS for extreme.",type:"recall"},
  {id:10,cat:"A",q:"What does NPS stand for in piping?",opts:["National Pipe Standard","Nominal Pipe Size","New Pipe Schedule","Natural Pipe Sizing"],ans:1,exp:"NPS = Nominal Pipe Size. It's a dimensionless designator (NPS 2 = approximately 2\" but not exactly). The actual OD is fixed for each NPS; wall thickness varies with schedule.",type:"recall"},
  {id:11,cat:"A",q:"A pipe's allowable working pressure depends on:",opts:["Only the diameter","Material, wall thickness (schedule), temperature, and applicable code allowable stresses","Only the length","Only the schedule number"],ans:1,exp:"Working pressure = (2 × S × t) ÷ D, where S = allowable stress (material/temp dependent), t = wall thickness, D = outside diameter. Temperature derates allowable stress significantly.",type:"critical"},
  {id:12,cat:"A",q:"WHMIS labels on chemical containers must include:",opts:["Only the product name","Product identifier, hazard symbols, precautionary statements, supplier info, and first aid measures","Only the colour","Only the weight"],ans:1,exp:"WHMIS 2015 (GHS aligned) labels require: product identifier, supplier info, GHS pictograms, signal word, hazard statements, precautionary statements, and first aid measures.",type:"recall"},
  {id:13,cat:"A",q:"The minimum PPE for steamfitters working on an active steam system includes:",opts:["Safety glasses only","Hard hat, safety glasses, face shield, heat-resistant gloves, hearing protection, and steel-toed boots","Gloves only","Boots only"],ans:1,exp:"Steam at even low pressure causes severe burns instantly. Full PPE includes face shield (flash steam), heat-resistant gloves, hearing protection (valve noise), plus standard PPE.",type:"recall"},
  {id:14,cat:"A",q:"What is the take-out (make-up) dimension for a 90° butt-weld elbow on NPS 4 Schedule 40?",opts:["Same as pipe OD","Equal to 1.5 × nominal diameter for long radius (6\" for NPS 4)","Random","Equal to the pipe length"],ans:1,exp:"Long radius (LR) 90° elbow: center-to-face = 1.5 × NPS. For NPS 4: 1.5 × 4 = 6\". Short radius (SR): center-to-face = 1 × NPS = 4\". LR is standard; SR for tight spaces.",type:"critical"},
  {id:15,cat:"A",q:"A material test report (MTR) certifies:",opts:["Only the colour","Chemical composition and mechanical properties of the pipe/fitting material as tested by the manufacturer","Only the size","Only the weight"],ans:1,exp:"MTRs (also called mill certs or 3.1 certs) verify the material meets the ordered specification (ASTM A106 Gr.B, etc.) with actual chemical and mechanical test results.",type:"recall"},
  {id:16,cat:"A",q:"When threading carbon steel pipe, cutting oil is used to:",opts:["Clean the threads","Lubricate, cool, and flush chips to produce clean threads and extend die life","Colour the pipe","Measure the threads"],ans:1,exp:"Thread cutting oil reduces friction/heat, flushes chips from the cutting area, extends die life, and produces cleaner threads for better joint integrity.",type:"recall"},

  // ═══ BLOCK B: Layout, Fabrication & Piping Installation (29) ═══
  {id:17,cat:"B",q:"The root gap for a butt weld joint on Schedule 40 pipe is typically:",opts:["Zero","1/16\" to 3/32\" (1.5-2.5mm)","1/4\"","1/2\""],ans:1,exp:"Standard root gap = 1/16-3/32\" allows full root penetration. Too narrow = lack of penetration. Too wide = burn-through. Consistent gap is maintained with spacers or tack welds.",type:"recall"},
  {id:18,cat:"B",q:"A beveled pipe end for butt welding typically has what included angle?",opts:["30°","37.5° per side (75° included V-groove)","45° per side","90°"],ans:1,exp:"Standard V-groove: 37.5° per side = 75° included angle with a 1/16\" root face (land). This is the most common butt weld preparation for pipe welding.",type:"recall"},
  {id:19,cat:"B",q:"Pipe hangers must be spaced based on:",opts:["Random placement","Pipe size, material, operating temperature, and code-specified maximum spans","Convenience only","Every 10 feet regardless"],ans:1,exp:"Hanger spacing depends on pipe size (larger = longer span allowed), material (steel vs copper), contents weight, insulation weight, and temperature (expansion). MSS SP-69 provides guidance.",type:"recall"},
  {id:20,cat:"B",q:"An expansion loop in a steam line is designed to:",opts:["Increase pressure","Absorb thermal expansion of the pipe to prevent excessive stress on anchors and equipment","Reduce flow","Filter steam"],ans:1,exp:"Steel pipe expands ~1\" per 100 feet per 100°F temperature rise. Expansion loops, offsets, and bellows absorb this growth, preventing overstressing pipes, supports, and connected equipment.",type:"recall"},
  {id:21,cat:"B",q:"The SMAW welding process (Stick) uses which electrode designation for carbon steel pressure pipe?",opts:["E6010 and E7018","E308L","ER70S-6","E410"],ans:0,exp:"E6010 (root pass — deep penetration, all positions) and E7018 (fill and cap — low hydrogen, strong, clean). This is the most common electrode combination for pressure pipe welding.",type:"recall"},
  {id:22,cat:"B",q:"When fabricating a mitered elbow from straight pipe, the miter angle for a 90° turn with 3 cuts is:",opts:["90° each","22.5° per miter cut","30° per cut","45° per cut"],ans:1,exp:"A 90° elbow cut into 3 pieces has 2 miter joints. Each joint turns the pipe 90° ÷ 2 = 45°, and the miter angle at each joint = 45° ÷ 2 = 22.5° (general formula: miter angle = total angle ÷ (2 × number of joints), where joints = pieces − 1).",type:"critical"},
  {id:23,cat:"B",q:"Flange bolt tightening should follow what pattern?",opts:["Clockwise sequence","Star (cross) pattern to evenly compress the gasket","Random sequence","Opposite pairs only"],ans:1,exp:"Star pattern tightening ensures even gasket compression. Multiple passes (25% → 50% → 75% → 100% of final torque) prevent warping and ensure uniform sealing pressure.",type:"procedure"},
  {id:24,cat:"B",q:"A raised face (RF) flange gasket sits on:",opts:["The entire flange face","The raised portion only, providing concentrated sealing pressure","The bolt holes","The pipe ID"],ans:1,exp:"The raised face concentrates bolt load onto a smaller gasket area, increasing sealing pressure. RF flanges use standard gaskets. RTJ (Ring Type Joint) flanges use metal ring gaskets for higher pressures.",type:"recall"},
  {id:25,cat:"B",q:"What is the purpose of a pipe alignment clamp during fit-up?",opts:["Cosmetic","Align pipe ends for consistent root gap and prevent hi-lo (mismatch) before tack welding","Measure length","Cut pipe"],ans:1,exp:"Alignment clamps center the pipe ends, ensure consistent root gap, and minimize hi-lo (wall mismatch). Critical for achieving proper root penetration and meeting code requirements.",type:"recall"},
  {id:26,cat:"B",q:"GTAW (TIG) welding is preferred for root passes on pressure pipe because:",opts:["It's fastest","It provides excellent control, full penetration, and a clean root with no slag inclusions","It's cheapest","It requires no skill"],ans:1,exp:"TIG provides precise heat control, clean welds with no slag, excellent root penetration, and X-ray quality weld quality. Standard for nuclear, high-pressure, and alloy piping root passes.",type:"recall"},
  {id:27,cat:"B",q:"Socket weld fittings require what gap between the pipe end and the fitting shoulder?",opts:["Zero — fully bottomed out","1/16\" (1.5mm) gap to allow for thermal expansion and prevent bottoming stress","1/4\" gap","1\" gap"],ans:1,exp:"Insert pipe fully into socket weld fitting, then pull back 1/16\" before tacking. This gap prevents thermal expansion from cracking the weld. Mark the pipe before insertion as a reference.",type:"procedure"},
  {id:28,cat:"B",q:"Pipe threading for NPS 2 and smaller uses which standard?",opts:["Metric threads","NPT (National Pipe Taper) — tapered threads that seal as tightened","Straight threads only","No standard exists"],ans:1,exp:"NPT threads taper at 3/4\" per foot. As the tapered male thread enters the tapered female fitting, the threads compress and seal. Thread sealant (tape or compound) ensures leak-free joints.",type:"recall"},
  {id:29,cat:"B",q:"When cutting stainless steel pipe, what must be avoided?",opts:["Using cutting oil","Contamination from carbon steel tools (grinding discs, wire brushes, clamps)","Cutting too slow","Using a hacksaw"],ans:1,exp:"Carbon steel contamination on stainless steel causes galvanic corrosion. Use dedicated stainless-only cut-off wheels, wire brushes, grinding discs, and clamps. Segregate tools.",type:"procedure"},
  {id:30,cat:"B",q:"A 150# flange is rated for what maximum pressure at 100°F?",opts:["150 PSI","285 PSI (per ASME B16.5 pressure-temperature rating)","500 PSI","1000 PSI"],ans:1,exp:"The 150# class designation doesn't equal 150 PSI! At 100°F, ASME B16.5 rates 150# carbon steel flanges at 285 PSI. Pressure rating decreases as temperature increases.",type:"critical"},
  {id:31,cat:"B",q:"Thermal expansion of carbon steel pipe is approximately:",opts:["Zero","0.75\" per 100 feet per 100°F rise (6.33 × 10⁻⁶ in/in/°F)","2\" per foot","Unpredictable"],ans:1,exp:"Carbon steel: ~0.75\" per 100ft per 100°F. A 200ft steam line going from 70°F to 370°F (300°F rise) expands: 0.75 × 2 × 3 = 4.5\". This growth must be accommodated.",type:"critical"},
  {id:32,cat:"B",q:"Brazing differs from soldering in that brazing:",opts:["Uses lower temperature","Uses filler metal with a melting point above 840°F (450°C)","Is weaker than solder","Doesn't require flux"],ans:1,exp:"Brazing: filler metal melts above 840°F (450°C) but below base metal melting point. Soldering: below 840°F. Brazing produces stronger joints and is required for refrigeration and high-pressure copper.",type:"recall"},
  {id:33,cat:"B",q:"A weld procedure specification (WPS) defines:",opts:["Only the welder's name","All essential variables: process, filler metal, base metal, preheat, interpass temp, position, technique","Only the pipe size","Only the joint type"],ans:1,exp:"WPS documents every variable needed to produce a code-compliant weld: process (SMAW, GTAW), materials, electrodes, preheat, amperage range, travel speed, positions, PWHT requirements.",type:"recall"},
  {id:34,cat:"B",q:"Post-weld heat treatment (PWHT) on carbon steel pipe is required when:",opts:["Always","Wall thickness exceeds code limits (typically >3/4\" or 19mm for carbon steel) or service requires it","Never","Only for stainless"],ans:1,exp:"PWHT relieves residual welding stresses. Required by ASME B31.1/B31.3 when wall thickness exceeds limits, for certain materials, or harsh service conditions (sour gas, lethal service).",type:"recall"},
  {id:35,cat:"B",q:"Non-destructive examination (NDE) of pipe welds includes:",opts:["Visual only","Radiography (X-ray), ultrasonic, magnetic particle, liquid penetrant, and visual examination","Only hammering","Only paint inspection"],ans:1,exp:"NDE methods detect weld defects without destroying the weld. Radiography and UT for internal defects; MT for surface/near-surface on ferromagnetic; PT for surface defects on all materials.",type:"recall"},
  {id:36,cat:"B",q:"When installing a reducer in a horizontal steam line, it should be:",opts:["Concentric always","Eccentric with flat on bottom (to prevent condensate pooling)","Eccentric with flat on top","Installed vertically"],ans:1,exp:"Eccentric reducer, flat on bottom: prevents condensate from pooling at the reduction. On pump suction lines: flat on top to prevent vapor pockets. This is a frequently tested exam question.",type:"critical"},
  {id:37,cat:"B",q:"A pipe's developed length for bending is calculated using:",opts:["Just the straight length","The neutral axis radius and the bend angle: L = (2π × R × angle) ÷ 360","Only the pipe diameter","Only the bend angle"],ans:1,exp:"Developed length = (2πR × angle) ÷ 360, where R = centerline radius of the bend. This determines how much straight pipe is consumed by the bend.",type:"critical"},
  {id:38,cat:"B",q:"Purging with inert gas during stainless steel welding prevents:",opts:["Nothing","Oxidation (sugaring) of the root side, which weakens and corrodes the weld","The pipe from moving","Cooling too fast"],ans:1,exp:"Stainless steel root passes require argon purge on the back side. Without purging, chromium oxidizes (sugaring), depleting corrosion resistance and creating a brittle, porous root.",type:"recall"},
  {id:39,cat:"B",q:"An anchor point in a piping system:",opts:["Allows movement","Fixes the pipe rigidly at that point, forcing thermal expansion in controlled directions","Only supports weight","Is temporary"],ans:1,exp:"Anchors fix the pipe, controlling where expansion occurs. They divide the system into segments with predictable expansion direction, directing movement to expansion joints or loops.",type:"recall"},
  {id:40,cat:"B",q:"The bolt torque for a flanged joint depends on:",opts:["Only bolt size","Bolt size and grade, gasket type, flange rating, and required gasket compression","Only the gasque","Only the wrench"],ans:1,exp:"Proper bolt torque ensures adequate gasket compression for sealing without overstressing bolts or flanges. Torque values come from engineering tables considering all these factors.",type:"recall"},
  {id:41,cat:"B",q:"Spring hangers on hot piping systems:",opts:["Are decorative","Support the pipe weight while allowing vertical movement from thermal expansion","Prevent movement","Only for cold pipes"],ans:1,exp:"Spring hangers maintain support load while the pipe moves vertically (up when hot, down when cold). Variable springs for moderate movement; constant springs for large displacement.",type:"recall"},
  {id:42,cat:"B",q:"A pipe shoe allows:",opts:["Nothing special","The pipe to slide along a support while the shoe protects the pipe insulation from damage","Walking on the pipe","Electrical connection"],ans:1,exp:"Pipe shoes lift insulated pipe off the support steel, allowing axial sliding while protecting the insulation and pipe from abrasion at the support point.",type:"recall"},
  {id:43,cat:"B",q:"Grooved pipe couplings (Victaulic) provide:",opts:["Permanent rigid joints","Quick mechanical connection with flexibility, vibration isolation, and easy disassembly","Welded joints","Threaded joints"],ans:1,exp:"Grooved couplings: fast installation (no welding/threading), allow angular deflection and axial movement, isolate vibration, and can be disassembled for maintenance. Common for sprinkler and HVAC.",type:"recall"},
  {id:44,cat:"B",q:"What is the included angle for a standard V-groove weld preparation on pipe?",opts:["30°","60° to 75° depending on wall thickness and code","90°","120°"],ans:1,exp:"Standard V-groove: 60° (30° per side) for thinner walls, 75° (37.5° per side) for standard. The wider groove provides better access for the root pass but requires more fill material.",type:"recall"},
  {id:45,cat:"B",q:"Pipe insulation material for steam lines above 250°F is typically:",opts:["Fiberglass only","Calcium silicate, mineral wool, or perlite rated for the operating temperature","Foam rubber","Polystyrene"],ans:1,exp:"High-temperature insulation: calcium silicate (to 1200°F), mineral wool (to 1200°F), perlite. Fiberglass is limited to ~450°F. Foam/polystyrene melt at steam temperatures.",type:"recall"},

  // ═══ BLOCK C: Rigging, Hoisting & Lifting (15) ═══
  {id:46,cat:"C",q:"What is the WLL formula for wire rope (6×19)?",opts:["D × 10","D² × 8 (diameter in inches squared × 8 = tons)","D × 5","D² × 4"],ans:1,exp:"WLL = D² × 8 for 6×19 wire rope. Example: 1/2\" rope = (0.5)² × 8 = 2 tons. This formula may be provided on the Red Seal exam.",type:"critical"},
  {id:47,cat:"C",q:"A chain hoist rated for 2 tons is used to lift a pipe spool weighing 3,000 lbs. Is this safe?",opts:["No, it's overloaded","Yes, 2 tons = 4,000 lbs which exceeds the 3,000 lb load","Need more information","It depends on the chain length"],ans:1,exp:"2 tons = 4,000 lbs. The load is 3,000 lbs which is within the 4,000 lb rating (75% capacity). Safe, but always verify load weight and rigging before lifting.",type:"critical"},
  {id:48,cat:"C",q:"When rigging a pipe to maintain level during a lift, the sling attachment points must be:",opts:["At the ends","Positioned so the centre of gravity is between and below the attachment points","Anywhere convenient","At one end only"],ans:1,exp:"The centre of gravity (CG) must be directly below the hook/crane attachment. If CG is off-centre, the pipe tilts. Use adjustable slings or a spreader beam for balance.",type:"recall"},
  {id:49,cat:"C",q:"Choker hitch capacity is approximately what percentage of a sling's vertical capacity?",opts:["100%","75%","50%","125%"],ans:1,exp:"Choker hitch reduces capacity to ~75% due to the sharp bend at the choke point. Basket hitch = ~200% of vertical (two legs sharing load). Always apply proper sling angle factors.",type:"recall"},
  {id:50,cat:"C",q:"Before operating a forklift to move pipe, what must a steamfitter verify?",opts:["Nothing","Load weight, fork capacity at the required reach, proper securing of the load, and travel path clearance","Only the fuel level","Only the key"],ans:1,exp:"Verify: load doesn't exceed rated capacity at the working radius, load is balanced and secured, travel path is clear, forks are under CG, and operator is licensed/trained.",type:"procedure"},
  {id:51,cat:"C",q:"A come-along (lever hoist) must never be used to:",opts:["Pull pipe","Lift personnel or as a permanent support — it's for temporary rigging and pulling only","Move equipment","Position pipe"],ans:1,exp:"Come-alongs are for temporary pulling/positioning only. Never for lifting people, not for permanent supports, and never loaded beyond their rated capacity.",type:"recall"},
  {id:52,cat:"C",q:"When lifting heavy valve assemblies, the lift points should be:",opts:["The handwheel","The valve body lifting lugs or sling around the body — never the handwheel or actuator","The stem","The flanges"],ans:1,exp:"Use manufacturer-designated lifting lugs. If no lugs, sling around the body. Never lift by handwheel (can break off), stem (bends), or actuator (not designed for lift loads).",type:"procedure"},
  {id:53,cat:"C",q:"A pipe roller allows:",opts:["Nothing special","The pipe to move axially during thermal expansion while supporting its weight","Pipe to spin freely","Only vertical movement"],ans:1,exp:"Pipe rollers support the pipe's dead weight while allowing it to slide axially as it expands and contracts with temperature changes. Critical for long straight runs of steam piping.",type:"recall"},
  {id:54,cat:"C",q:"The minimum sling angle from horizontal should be:",opts:["30°","60° — below this, sling stress increases dramatically","45°","90°"],ans:1,exp:"Below 60° from horizontal, the sling tension increases sharply and horizontal crushing forces on the load become dangerous. At 30°, sling tension is 2× the load divided by number of legs.",type:"recall"},
  {id:55,cat:"C",q:"When using a crane to set large pipe sections, the signal person must:",opts:["Stand under the load","Be clearly visible to the operator, use standard hand signals, and have authority to stop the lift","Stand beside the crane","Operate the crane remotely"],ans:1,exp:"One designated signal person uses standard signals, maintains clear line of sight with operator, and has sole authority to direct the lift. Anyone can give STOP signal.",type:"recall"},
  {id:56,cat:"C",q:"Shackle pin orientation when rigging should be:",opts:["Any direction","Pin loaded along its axis (not in the direction that could unscrew it)","Pin pointing down always","Doesn't matter"],ans:1,exp:"Orient the shackle pin so the load doesn't tend to unscrew it. The pin should be loaded in shear, not in a direction that could roll it open. Bolt-type shackles with cotter pins are more secure.",type:"recall"},
  {id:57,cat:"C",q:"A tugger (air winch) is used on pipe jobs to:",opts:["Weld pipe","Pull, position, and lift pipe spools and equipment in fabrication and installation","Cut pipe","Test pipe"],ans:1,exp:"Tuggers provide controlled pulling/lifting force for positioning pipe, pulling through racks, and rigging in areas where cranes can't reach. Air-powered for hazardous areas.",type:"recall"},
  {id:58,cat:"C",q:"Rigging hardware must be inspected:",opts:["Once a year","Before each use — check for cracks, deformation, corrosion, and proper rating","Only when new","Never"],ans:1,exp:"Pre-use inspection: check slings for cuts/wear, shackles for pin straightness, hooks for throat opening, all hardware for damage/deformation. Remove damaged equipment immediately.",type:"procedure"},
  {id:59,cat:"C",q:"The safe working load of rigging hardware is determined by:",opts:["Guessing","The manufacturer's rated WLL stamped on the equipment","The colour","The age"],ans:1,exp:"WLL is stamped/tagged on all rigging hardware by the manufacturer. Never exceed it. If the rating is illegible or missing, remove from service.",type:"recall"},
  {id:60,cat:"C",q:"When setting a heavy vessel with a crane, outriggers must be:",opts:["Retracted","Fully extended and on solid ground/pads to maximize crane stability and capacity","Partially extended","Not required"],ans:1,exp:"Outriggers must be fully extended and set on solid ground or crane pads. Partially extended outriggers drastically reduce crane capacity. Ground must support the concentrated load.",type:"recall"},

  // ═══ BLOCK D: Steam & Condensate Systems (24) ═══
  {id:61,cat:"D",q:"What is the primary function of a steam trap?",opts:["Trap steam in the system","Remove condensate, air, and non-condensables while preventing live steam from escaping","Filter steam","Regulate pressure"],ans:1,exp:"Steam traps discharge condensate (water) and air while keeping live steam in the system. Failed traps waste energy (blowing steam) or flood equipment (backed-up condensate).",type:"recall"},
  {id:62,cat:"D",q:"The three main types of steam traps are:",opts:["Ball, gate, globe","Mechanical (float/bucket), thermostatic (bellows/bimetallic), and thermodynamic (disc)","Only mechanical","Only thermodynamic"],ans:1,exp:"Mechanical: float/inverted bucket (respond to condensate level). Thermostatic: bellows/bimetallic (respond to temperature difference). Thermodynamic: disc (respond to flash steam velocity).",type:"recall"},
  {id:63,cat:"D",q:"Low pressure steam is defined as:",opts:["Below 15 PSI (103 kPa) gauge","Below 100 PSI","Below 500 PSI","Below 1000 PSI"],ans:0,exp:"Low pressure: ≤15 PSIG. Medium: 15-100 PSIG. High: >100 PSIG. Low pressure systems have different code requirements, material requirements, and operator certification levels.",type:"recall"},
  {id:64,cat:"D",q:"Water hammer in a steam system is caused by:",opts:["High pressure","Condensate accumulation being picked up by high-velocity steam, creating a slug that impacts piping/fittings","Low pressure","Clean steam"],ans:1,exp:"Steam water hammer: condensate collects (poor drainage), steam pushes it at high velocity, and the water slug impacts elbows, valves, or dead ends with tremendous force. Can rupture piping.",type:"critical"},
  {id:65,cat:"D",q:"To prevent water hammer in steam piping, what measures are taken?",opts:["Increase pressure","Proper pitch (slope) toward drip legs, adequate drip legs, properly sized steam traps, and slow warm-up","Decrease pipe size","Remove insulation"],ans:1,exp:"Slope all steam mains toward drip legs (1/4\" per 10 ft minimum), install drip legs at all low points, use properly sized traps, and warm up systems slowly to clear condensate.",type:"procedure"},
  {id:66,cat:"D",q:"A drip leg (drip pocket) in a steam main collects:",opts:["Steam","Condensate that forms as steam transfers heat through the pipe walls","Air only","Oil only"],ans:1,exp:"As steam travels through piping, heat loss through pipe walls condenses some steam. Drip legs (vertical pockets at low points) collect this condensate for removal by steam traps.",type:"recall"},
  {id:67,cat:"D",q:"The minimum drip leg diameter should be:",opts:["Half the main size","Equal to the steam main size for mains ≤4\", at least half for larger mains","1/4\" always","Same as trap connection"],ans:1,exp:"Drip legs should be full pipe size for mains up to 4\". For larger mains, minimum half the pipe size. Undersized drip legs can't capture all condensate, leading to water hammer.",type:"recall"},
  {id:68,cat:"D",q:"A boiler safety valve must be set to open at:",opts:["Any pressure","The boiler's MAWP (Maximum Allowable Working Pressure) or below","Twice MAWP","Half MAWP"],ans:1,exp:"Safety valves must be set at or below MAWP and must relieve the full steaming capacity of the boiler. They are the last line of defense against catastrophic boiler explosion. Legally required and tested regularly.",type:"recall"},
  {id:69,cat:"D",q:"A condensate return system returns condensate to the boiler because:",opts:["It's cheaper than draining it","Condensate is hot, treated water — returning it saves energy, chemical treatment costs, and makeup water","It's required by law only","For appearance"],ans:1,exp:"Returning condensate: saves ~20% of fuel (condensate is already hot), saves chemical treatment costs, saves makeup water and sewage costs, and reduces boiler thermal stress.",type:"recall"},
  {id:70,cat:"D",q:"Flash steam occurs when:",opts:["Steam condenses","High-pressure condensate is released to a lower pressure — some re-evaporates into steam","Water freezes","Steam is superheated"],ans:1,exp:"Hot condensate at saturation temperature contains more energy than water at the lower system pressure can hold. The excess energy flashes some water back to steam. Flash tanks capture this energy.",type:"critical"},
  {id:71,cat:"D",q:"A steam pressure reducing valve (PRV) station requires:",opts:["Just the PRV","PRV, upstream strainer, safety valve downstream, pressure gauges, and bypass","Only a bypass","Only a gauge"],ans:1,exp:"PRV station: upstream isolation valve, strainer (protects PRV internals), PRV, downstream safety valve (set above reduced pressure), gauges both sides, and bypass for maintenance.",type:"procedure"},
  {id:72,cat:"D",q:"Superheat in steam means:",opts:["Steam is very wet","Steam temperature is above the saturation temperature for its pressure — it contains no moisture","Steam is at saturation","Steam is condensing"],ans:1,exp:"Superheated steam: heated beyond saturation temperature. It behaves more like a gas, carries more energy per pound, and won't condense until cooled back to saturation temperature.",type:"recall"},
  {id:73,cat:"D",q:"When warming up a cold steam system, the procedure is:",opts:["Open the main valve fully immediately","Open slowly, crack the valve to allow gradual warming and condensate drainage through traps before fully opening","Close all drains","Bypass the traps"],ans:1,exp:"Slow warm-up: crack the steam supply valve, allow condensate to drain through traps, watch for water hammer, gradually increase flow. Rapid warm-up causes thermal shock, water hammer, and gasket failures.",type:"procedure"},
  {id:74,cat:"D",q:"A boiler blowdown removes:",opts:["Steam","Accumulated dissolved solids, sediment, and sludge from the boiler water","Only air","Only steam"],ans:1,exp:"Blowdown removes: bottom blowdown (sludge/sediment), surface blowdown (dissolved solids, foam). Controls water chemistry to prevent scale, corrosion, and carryover.",type:"recall"},
  {id:75,cat:"D",q:"An inverted bucket steam trap works by:",opts:["Temperature sensing","The bucket floats (inverted) on condensate when steam is present, closing the valve. Condensate fills the bucket, it sinks, opening the valve to discharge.","Pressure differential","Disc action"],ans:1,exp:"Inverted bucket: steam enters bucket, it floats and closes valve (retains steam). As steam condenses, bucket fills with water, sinks, opens valve, and condensate discharges. Very robust for high-pressure.",type:"recall"},
  {id:76,cat:"D",q:"A vacuum breaker on a steam system prevents:",opts:["High pressure","Vacuum formation during shutdown that could collapse the vessel or cause water siphonage","Steam leaks","Noise"],ans:1,exp:"When steam condenses in a closed vessel during shutdown, volume decreases dramatically creating vacuum. Vacuum breakers allow air in to prevent vessel collapse and backflow.",type:"recall"},
  {id:77,cat:"D",q:"Steam quality of 95% means:",opts:["95% air","95% steam (vapor) and 5% entrained water droplets (moisture)","95% pressure","95% temperature"],ans:1,exp:"Steam quality = percentage of vapor in the steam-water mixture. 95% quality = 5% moisture. Wet steam reduces heat transfer efficiency and can damage equipment. Separators improve quality.",type:"recall"},
  {id:78,cat:"D",q:"The proper way to test a steam trap is:",opts:["Ignore it","Use temperature measurement, ultrasonic testing, or visual/conductivity testing to verify proper operation","Just look at it","Hit it with a hammer"],ans:1,exp:"Trap testing: temperature (inlet hot, outlet cooler for working trap), ultrasonic (detects internal leaking), visual (sight glass/test valve shows condensate vs steam), or conductivity.",type:"procedure"},
  {id:79,cat:"D",q:"A desuperheater reduces steam temperature by:",opts:["Removing heat with fins","Injecting water into the superheated steam flow","Adding air","Reducing pressure only"],ans:1,exp:"Desuperheaters spray controlled amounts of water into superheated steam. The water absorbs superheat as it evaporates, bringing steam closer to saturation temperature.",type:"recall"},
  {id:80,cat:"D",q:"Hartford Loop on a low-pressure steam boiler prevents:",opts:["High pressure","Boiler water from draining back through the condensate return if a return line fails","Noise","Corrosion"],ans:1,exp:"The Hartford Loop connects the return line to the equalizer below the waterline. If the return line breaks, the loop limits how low the boiler water can drop, preventing dry-fire.",type:"recall"},
  {id:81,cat:"D",q:"A feedwater system supplies:",opts:["Fuel to the boiler","Treated water to the boiler to replace water lost to steam production and blowdown","Steam to the building","Air to the burner"],ans:1,exp:"The feedwater system: supplies makeup water (treated to remove hardness, oxygen, and contaminants), returns condensate, and uses deaerators/chemical treatment to protect the boiler from corrosion and scale.",type:"recall"},
  {id:82,cat:"D",q:"Steam system insulation reduces:",opts:["Noise only","Heat loss (saving fuel), condensation formation, and burn hazard to personnel","Weight","Vibration"],ans:1,exp:"Insulation: reduces heat loss (major energy savings), minimizes condensate formation (less drip leg load), and protects workers from burn contact with hot piping.",type:"recall"},
  {id:83,cat:"D",q:"A failed-open steam trap wastes energy because:",opts:["It stops condensate flow","Live steam passes directly to the condensate return, wasting the energy that should heat the process","It makes noise only","It has no effect"],ans:1,exp:"A blow-through trap wastes live steam — up to $5,000-15,000/year per trap. Regular trap surveys identify failed traps. Estimated 15-30% of traps in any plant are failed at any time.",type:"critical"},
  {id:84,cat:"D",q:"When installing high-pressure steam piping (>100 PSIG), the work must be performed by:",opts:["Anyone","Licensed steamfitters following ASME B31.1 with qualified welding procedures and inspected by a B51 inspector","Helpers only","Plumbers"],ans:1,exp:"High-pressure steam is inherently dangerous. Work must follow ASME B31.1, welders must be qualified, welds must be NDE inspected, and the system registered with the provincial authority (TSSA in Ontario).",type:"recall"},

  // ═══ BLOCK E: Heating, Cooling & Process Piping (38) ═══
  {id:85,cat:"E",q:"A hydronic heating system operating above 250°F requires:",opts:["Standard plumbing materials","Materials and installation per ASME B31.1 or B31.9 pressure piping codes","PVC piping","No special requirements"],ans:1,exp:"High-temperature hot water (HTHW) systems operate above atmospheric boiling point under pressure. They require pressure-rated materials, safety relief devices, and code-compliant installation.",type:"recall"},
  {id:86,cat:"E",q:"A chilled water system typically operates at what temperature range?",opts:["180-200°F","40-45°F (4-7°C) supply, 55-60°F return","32°F exactly","100°F"],ans:1,exp:"Chilled water: ~40-45°F supply, returns at ~55-60°F after absorbing heat from the building. Glycol is added if any part of the system is exposed to freezing conditions.",type:"recall"},
  {id:87,cat:"E",q:"A balancing valve on a hydronic system is used to:",opts:["Shut off flow","Regulate flow to each branch to ensure proper heat/cooling distribution throughout the building","Increase pressure","Filter water"],ans:1,exp:"Balancing valves (manual or automatic) adjust flow to design rates in each branch/zone. Without balancing, close circuits get too much flow and distant circuits get too little.",type:"recall"},
  {id:88,cat:"E",q:"Process piping for chemical service must consider:",opts:["Only size","Material compatibility with the chemical, temperature, pressure, and concentration","Only pressure","Only colour"],ans:1,exp:"Process piping material selection: chemical compatibility (corrosion resistance), temperature rating, pressure rating, and concentration. Wrong material = rapid corrosion, leaks, and safety hazards.",type:"recall"},
  {id:89,cat:"E",q:"A glycol system requires what additional considerations versus plain water?",opts:["None","Larger pump, expansion tank sizing, compatible seals/gaskets, and corrosion inhibitor maintenance","Smaller pipes","No expansion tank"],ans:1,exp:"Glycol: more viscous (larger pump/motor), lower heat capacity (higher flow rates), requires compatible seals (some rubbers swell), and corrosion inhibitors must be monitored and maintained.",type:"recall"},
  {id:90,cat:"E",q:"Copper tube used for refrigeration must be:",opts:["Type M","ACR (Air Conditioning and Refrigeration) grade — cleaned, dehydrated, and nitrogen-sealed","Type K","DWV"],ans:1,exp:"ACR copper is cleaned of oils and oxides, dried, and sealed with nitrogen to prevent internal contamination. Regular plumbing copper contains residual drawing oils that contaminate refrigerant systems.",type:"recall"},
  {id:91,cat:"E",q:"A cooling tower rejects heat from a chilled water system by:",opts:["Mechanical refrigeration","Evaporating water to cool the condenser water circuit","Electrical cooling","Chemical cooling"],ans:1,exp:"Cooling towers spray warm condenser water over fill media while air flows through. Evaporation of a small percentage cools the remaining water. This rejects the building's heat to the atmosphere.",type:"recall"},
  {id:92,cat:"E",q:"An air separator in a hydronic system removes:",opts:["Dust","Dissolved and entrained air that causes corrosion, noise, and reduces heat transfer","Water","Glycol"],ans:1,exp:"Air separators create low-velocity zones where dissolved air comes out of solution and collects for venting. Air in hydronic systems causes: noise, corrosion (oxygen), air locks, and pump cavitation.",type:"recall"},
  {id:93,cat:"E",q:"The purpose of a strainer upstream of a control valve is:",opts:["Increase pressure","Capture debris that could damage the valve seat and plug","Reduce flow","Heat the fluid"],ans:1,exp:"Y-strainers or basket strainers upstream of control valves, traps, and pumps capture welding slag, scale, and debris that would damage precision valve internals.",type:"recall"},
  {id:94,cat:"E",q:"A pressure-independent control valve (PICV) provides:",opts:["Only on/off control","Constant flow regardless of system pressure fluctuations — combining balancing and control in one valve","Only manual adjustment","Only pressure control"],ans:1,exp:"PICVs maintain set flow rate regardless of pressure changes in the system. They eliminate the need for separate balancing valves and simplify system commissioning.",type:"recall"},
  {id:95,cat:"E",q:"When soldering/brazing refrigeration copper, the joint must be purged with:",opts:["Air","Dry nitrogen to prevent internal copper oxide formation","Oxygen","CO₂"],ans:1,exp:"Nitrogen purge prevents internal oxidation during brazing. Copper oxide flakes off inside the system, clogging expansion valves, filter-driers, and compressor passages.",type:"procedure"},
  {id:96,cat:"E",q:"A heat exchanger (plate or shell-and-tube) transfers heat between:",opts:["Only gases","Two fluid streams without mixing them — maintaining separation between circuits","Only solids","Only identical fluids"],ans:1,exp:"Heat exchangers separate two fluid circuits (e.g., steam heating water, glycol cooling process fluid) while maximizing heat transfer between them. No mixing of fluids occurs.",type:"recall"},
  {id:97,cat:"E",q:"When pressure testing a refrigeration system, what gas is used?",opts:["Refrigerant","Dry nitrogen (with trace refrigerant for leak detection if needed)","Oxygen","Compressed air"],ans:1,exp:"Dry nitrogen: inert, dry, and safe for pressure testing. Never use oxygen (explosion risk with oil) or compressed air (contains moisture). Trace refrigerant added for electronic leak detection.",type:"procedure"},
  {id:98,cat:"E",q:"ASME B31.3 governs:",opts:["Power piping","Process piping in refineries, chemical plants, and industrial facilities","Residential plumbing","Fire sprinklers"],ans:1,exp:"B31.3 Process Piping: covers piping in petroleum refineries, chemical/pharmaceutical plants, textile mills, paper mills, and similar industrial applications with diverse fluids and conditions.",type:"recall"},
  {id:99,cat:"E",q:"A check valve in a hydronic system prevents:",opts:["Forward flow","Reverse flow that could cause pump damage or unwanted circulation between zones","Pressure buildup","Temperature change"],ans:1,exp:"Check valves: prevent reverse flow during pump shutdown, prevent thermosiphoning (unwanted gravity circulation), and protect pumps from backflow. Spring-loaded or swing type.",type:"recall"},
  {id:100,cat:"E",q:"Fan coil units in a hydronic system:",opts:["Generate chilled water","Circulate air over a coil carrying hot or chilled water to heat or cool a space","Produce steam","Treat water"],ans:1,exp:"Fan coil units: a fan blows room air across a coil carrying heated or chilled water. Control valves modulate water flow to maintain room temperature. Common in hotels, offices, hospitals.",type:"recall"},
  {id:101,cat:"E",q:"When installing underground chilled water piping, what insulation is required?",opts:["None","Closed-cell foam insulation with moisture barrier to prevent condensation and heat gain","Fiberglass only","No insulation needed underground"],ans:1,exp:"Underground chilled water pipes need insulation to prevent heat gain from soil (efficiency loss) and a vapor barrier to prevent moisture intrusion that destroys insulation R-value.",type:"recall"},
  {id:102,cat:"E",q:"A variable speed drive on a hydronic pump saves energy by:",opts:["Running faster","Reducing pump speed to match actual system demand — pump energy drops with the cube of speed reduction","Increasing pressure","Running at constant speed"],ans:1,exp:"Pump affinity laws: power varies with the CUBE of speed. Reducing speed by 20% reduces energy by ~49%. Variable speed pumping is the single biggest energy saver in hydronic systems.",type:"critical"},
  {id:103,cat:"E",q:"Dielectric isolation is required where:",opts:["All connections","Dissimilar metals are joined (steel to copper) to prevent galvanic corrosion","Same metals meet","Plastic to metal"],ans:1,exp:"Galvanic corrosion: when dissimilar metals are in contact with an electrolyte (water), the less noble metal corrodes. Dielectric unions, flanges, or isolation couplings electrically separate them.",type:"recall"},
  {id:104,cat:"E",q:"A double-wall heat exchanger is required when:",opts:["Always","One fluid is potable water and the other is a potentially hazardous fluid (glycol, refrigerant, chemicals)","Never","Only for steam"],ans:1,exp:"Double-wall heat exchangers prevent cross-contamination if a leak occurs. Required by code when potable water could be contaminated by a non-potable fluid in the other circuit.",type:"recall"},
  {id:105,cat:"E",q:"When commissioning a hydronic system, the first step is:",opts:["Start the pumps immediately","Fill, flush, clean, vent air, verify pressure, and chemically treat the water before running pumps","Turn on the boiler","Set thermostats"],ans:1,exp:"Commission sequence: fill and flush system, clean with chemical cleaner, flush again, fill with treated water, vent all high points, verify expansion tank charge, then start pumps.",type:"procedure"},
  {id:106,cat:"E",q:"A pneumatic test on a piping system is more dangerous than hydrostatic because:",opts:["Water is heavier","Air stores much more energy than water under pressure — a failure causes explosive release","Pneumatic is easier","There's no difference"],ans:1,exp:"Compressed gas is highly compressible and stores enormous energy. A hydrostatic failure leaks; a pneumatic failure explodes. Pneumatic tests require engineering approval and safety precautions.",type:"recall"},
  {id:107,cat:"E",q:"An automatic air vent is installed at:",opts:["The lowest point","High points in the piping system where air naturally accumulates","The pump inlet","The boiler drain"],ans:1,exp:"Air rises to high points. Automatic air vents open when air accumulates (float drops) and close when water reaches the vent (float rises). Manual vents require periodic attention.",type:"recall"},
  {id:108,cat:"E",q:"A BTU meter measures:",opts:["Only temperature","Energy transfer: flow rate × temperature difference between supply and return = BTU/hour","Only flow","Only pressure"],ans:1,exp:"BTU meters calculate: Q = flow × ΔT × constant. They measure both flow rate and temperature differential, computing actual energy delivered to or removed from a zone. Used for tenant billing.",type:"recall"},
  {id:109,cat:"E",q:"Process piping for oxygen service requires:",opts:["Standard preparation","Scrupulously clean piping — all oil, grease, and contaminants removed. Oxygen + hydrocarbon = explosion.","Just rinsing","No special cleaning"],ans:1,exp:"Oxygen service: all components must be chemically cleaned and verified free of hydrocarbons. Even trace amounts of oil or grease in contact with concentrated oxygen can spontaneously ignite.",type:"critical"},
  {id:110,cat:"E",q:"A three-way mixing valve on a hydronic system:",opts:["Has three pipe connections","Blends return water with supply water to control loop temperature while maintaining constant flow","Only shuts off","Only opens"],ans:1,exp:"Three-way mixing valves: two inlets (hot supply + cooler return) and one outlet (mixed). The valve modulates the blend ratio to maintain the desired outlet temperature for the zone.",type:"recall"},
  {id:111,cat:"E",q:"Vibration isolation on pump connections prevents:",opts:["Nothing","Pump vibration from transmitting through the piping system causing noise and fatigue failures","Corrosion","Scale buildup"],ans:1,exp:"Flexible connectors (rubber, braided metal) on pump suction and discharge isolate vibration. Without them, pump vibration travels through piping, causing noise, loosening joints, and fatigue cracking.",type:"recall"},
  {id:112,cat:"E",q:"When testing fluctuations occur on a 24-hour air test of a piping system, the most likely cause is:",opts:["A leak","Change in ambient air temperature expanding/contracting the trapped air","Test gauge failure","System volume change"],ans:1,exp:"Temperature change causes pressure fluctuation in a sealed air test (Gay-Lussac's Law). A 10°F temperature rise causes ~2% pressure increase. This is the official Red Seal sample question answer.",type:"critical"},
  {id:113,cat:"E",q:"A chemical feed system on a hydronic loop maintains:",opts:["Only temperature","Proper water chemistry (pH, inhibitor levels, biocide) to prevent corrosion and biological growth","Only pressure","Only flow"],ans:1,exp:"Chemical treatment: maintains pH 8-10 (reduces corrosion), oxygen scavenger (prevents pitting), biocide (prevents bacterial growth), and corrosion inhibitor. Regular testing is essential.",type:"recall"},
  {id:114,cat:"E",q:"Pipe supports on a refrigeration system must allow for:",opts:["No movement","Thermal contraction (pipes shrink when cold) and vibration from compressor operation","Only vertical movement","Only weight"],ans:1,exp:"Refrigeration pipes contract when cold (opposite of steam). Supports must allow axial movement. Compressor vibration requires vibration isolators at the machine connections.",type:"recall"},
  {id:115,cat:"E",q:"The fill connection on a closed hydronic system requires:",opts:["Direct connection to the domestic supply","A backflow preventer (RPZ or air gap) between the potable water fill and the hydronic system","No protection","Only a valve"],ans:1,exp:"Hydronic water contains chemicals and may contain bacteria — it's non-potable. A backflow preventer (minimum RPZ) protects the potable water supply from contamination.",type:"procedure"},
  {id:116,cat:"E",q:"When piping dissimilar materials (steel to PVC), the transition requires:",opts:["Glue them together","Proper transition fittings and consideration of differential thermal expansion rates","Just a coupling","Welding"],ans:1,exp:"Dissimilar materials expand at different rates. Steel-to-PVC transitions need proper adapters (flanged or threaded) and flexible connections to accommodate differential movement.",type:"recall"},
  {id:117,cat:"E",q:"A pressure relief valve on a closed chilled water system is set to:",opts:["Any pressure","Above the maximum system operating pressure but within the equipment pressure rating","Minimum pressure","Atmospheric pressure"],ans:1,exp:"Relief valves protect closed systems from overpressure due to thermal expansion, pump deadheading, or system upsets. Set above normal operating but below the weakest component's rating.",type:"recall"},
  {id:118,cat:"E",q:"When brazing copper refrigeration pipe, the flame should be:",opts:["Oxidizing","Neutral to slightly reducing to prevent copper oxidation","Carburizing only","Maximum heat"],ans:1,exp:"Slight excess acetylene (reducing flame) prevents copper oxidation. Oxidizing flame causes scale that weakens the joint. Use silver brazing alloy with appropriate flux for dissimilar metals.",type:"procedure"},
  {id:119,cat:"E",q:"A thermostatic expansion valve (TXV) in a refrigeration system:",opts:["Compresses refrigerant","Meters refrigerant flow to the evaporator based on superheat, maintaining optimal evaporator performance","Only opens fully","Only closes fully"],ans:1,exp:"TXVs sense evaporator superheat via a sensing bulb and modulate refrigerant flow to maintain target superheat (typically 8-12°F). This maximizes evaporator efficiency across varying loads.",type:"recall"},
  {id:120,cat:"E",q:"HDPE (High-Density Polyethylene) piping is joined by:",opts:["Solvent cement","Heat fusion (butt fusion, socket fusion, or electrofusion)","Threaded joints","Soldering"],ans:1,exp:"HDPE is joined by heat fusion: butt fusion (heated faces pressed together), socket fusion, or electrofusion fittings. Creates monolithic, leak-free joints. Common for geo-exchange loops and underground.",type:"recall"},
  {id:121,cat:"E",q:"A condenser in a refrigeration system:",opts:["Cools the space","Rejects heat from the high-pressure refrigerant gas, condensing it to liquid","Absorbs heat","Meters refrigerant"],ans:1,exp:"The condenser removes heat absorbed in the evaporator plus compressor heat. High-pressure gas enters, rejects heat to air or water, and exits as high-pressure liquid.",type:"recall"},
  {id:122,cat:"E",q:"When installing underground process piping, cathodic protection may be required to:",opts:["Increase flow","Prevent corrosion of buried metallic piping from soil and stray electrical currents","Heat the pipe","Filter contaminants"],ans:1,exp:"Cathodic protection (sacrificial anodes or impressed current) protects buried steel pipe from galvanic and electrolytic corrosion. Required by code for many underground metallic piping systems.",type:"recall"},

  // ═══ BLOCK F: Renewable Energy Systems (8) ═══
  {id:123,cat:"F",q:"A geo-exchange (ground-source heat pump) system uses what as the heat source/sink?",opts:["Air","The relatively constant temperature of the earth (ground or groundwater)","Combustion","Solar only"],ans:1,exp:"Geo-exchange systems circulate fluid through underground loops, exchanging heat with the earth (~10°C year-round in most of Canada). Heating in winter, cooling in summer, very efficient.",type:"recall"},
  {id:124,cat:"F",q:"The piping loop in a closed-loop geo-exchange system is typically made of:",opts:["Copper","HDPE (High-Density Polyethylene) fused piping buried in boreholes or horizontal trenches","Cast iron","PVC"],ans:1,exp:"HDPE: chemically inert, flexible, heat-fusible joints (leak-free), long lifespan underground. Horizontal loops at 4-6 ft depth or vertical boreholes to 200-400 ft. Filled with water/antifreeze.",type:"recall"},
  {id:125,cat:"F",q:"An open-loop geo-exchange system uses:",opts:["Sealed buried piping","Groundwater pumped directly through the heat pump, then returned to the aquifer or surface","Only air","Only solar"],ans:1,exp:"Open-loop: well water pumped through the heat pump and discharged (return well or surface water). Higher efficiency but requires good water quality, sufficient flow, and discharge permits.",type:"recall"},
  {id:126,cat:"F",q:"The coefficient of performance (COP) of a geo-exchange heat pump is typically:",opts:["1.0 (100% efficient)","3.0-5.0 (delivers 3-5 units of heat per unit of electricity consumed)","10.0","0.5"],ans:1,exp:"COP 3-5 means for every 1 kW of electricity consumed, the system delivers 3-5 kW of heating. Much more efficient than electric resistance (COP=1) or gas furnace (efficiency <1).",type:"recall"},
  {id:127,cat:"F",q:"Solar thermal collectors heat:",opts:["Electricity","A heat transfer fluid (glycol/water) that transfers solar energy to a storage tank or heating system","Refrigerant directly","Air only"],ans:1,exp:"Flat plate or evacuated tube collectors absorb solar radiation, heating a glycol/water mixture that circulates to a storage tank. The heated water supplements domestic hot water or space heating.",type:"recall"},
  {id:128,cat:"F",q:"Antifreeze protection in a geo-exchange loop is typically provided by:",opts:["Calcium chloride","Propylene glycol or methanol mixed with water","Ethylene glycol always","Salt"],ans:1,exp:"Propylene glycol (non-toxic) or methanol are common. Ethylene glycol is toxic and not preferred for ground loops due to environmental concerns if a leak occurs. Concentration based on minimum expected temperature.",type:"recall"},
  {id:129,cat:"F",q:"A desuperheater on a geo-exchange heat pump:",opts:["Cools the space","Recovers waste heat from the refrigerant to preheat domestic hot water for free","Heats the ground","Defrosts the unit"],ans:1,exp:"Desuperheaters capture superheat from the compressor discharge to preheat DHW. Essentially free hot water when the heat pump is running for heating or cooling. Saves significant energy.",type:"recall"},
  {id:130,cat:"F",q:"When pressure testing a geo-exchange ground loop before backfilling, the test medium should be:",opts:["Air","Water or the glycol solution, held at test pressure for a minimum duration while inspecting","Nitrogen only","Steam"],ans:1,exp:"Pressure test the loop before burying (once buried, repairs are extremely expensive). Test with water at specified pressure for code-required duration. Document the test results.",type:"procedure"},
];
